import type { MetadataRoute } from "next"

// Icons for "Add to Home Screen" / installed-app use. The browser-tab favicons are
// app/favicon.ico, app/icon.svg and app/apple-icon.png, which Next.js links automatically.
// All of them are generated by scripts/generate-icons.mjs (npm run icons).
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Care Beacon",
    short_name: "Care Beacon",
    description: "Evidence-based medical information powered by AI and BC Cancer resources",
    start_url: "/",
    display: "standalone",
    background_color: "#ffffff",
    theme_color: "#0a0a0a",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
      { src: "/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  }
}
